[2854] = { en = "Wild Leather Armor", tier = 3,
  t = "Wild Leather-pantser",
  d = "$n, je vaardigheid als leerbewerker is al bekend. Ik heb kennis van het leerbewerken die je maar beter kunt leren... Wild Leather-pantser! Wild Leather gebruikt de sterke en chaotische eigenschappen van Wildvines. Die vind je in gebieden met veel planten en bij sommige wezens die daar leven. Pantser dat ermee gemaakt is, is het beste wat er bestaat voor een vakman met jouw vaardigheid, gegarandeerd.$B$BIk zal het je leren, maar je gaat een tijdje voor mij werken. De eerste prijs is gewoon tien stukken dik leer. Daarna bespreken we de details.",
  o = "Breng 10 Thick Leather naar Jangdor Swiftstrider in Camp Mojache.",
  p = "Laten we duidelijk zijn: je wordt mijn leerling terwijl je de kunst van Wild Leather-pantser leert. Wildvines zijn sterk en chaotisch. Daarom geven ze een willekeurig maar sterk voordeel aan het pantser dat je gaat maken, en dat pantser is al sterk. Maar deze kennis was voor mij niet makkelijk te krijgen.$b$bDe prijs om met dit proces te beginnen is tien stukken dik leer.$b$bAls dat gedaan is, beginnen we aan het werk dat je moet doen om de patronen te krijgen.",
  c = "Goed, $N, ik ben blij dat je mijn leerling wordt. Je hebt als leerbewerker een verstandige keuze gemaakt. Wie leren pantser draagt, zal bij jou in de rij staan zodra je de kunst van Wild Leather beheerst.$b$bLaten we aan het werk gaan - waar wil je beginnen?",
  g = { {"vaardigheid", "skill"}, {"leerbewerker", "leatherworker"}, {"maar beter kunt", "would be wise to"}, {"pantser", "armor"}, {"eigenschappen", "properties (eigenschap)"}, {"vakman", "craftsman"}, {"gegarandeerd", "guaranteed"}, {"leerling", "apprentice, student"}, {"willekeurig", "random"}, {"voordeel", "benefit, advantage"}, {"patronen", "patterns (patroon)"}, {"in de rij staan", "to line up for, clamor for"}, {"beheerst", "master (beheersen)"} },
},

[2855] = { en = "Wild Leather Shoulders", tier = 3,
  t = "Wild Leather-schouderstukken",
  d = "Wild Leather-schouderstukken ondersteunen het lichaam van de drager heel goed. Ze geven uitstekende bescherming aan de bovenarmen en aan de schouders. Zoals bij al het Wild Leather-pantser komt er een willekeurige maar heel sterke verbetering in het voorwerp terwijl de Wildvine erin wordt genaaid.$B$BVoor dit patroon heb ik zes Thick Armor Kits en een Wildvine nodig. Dat moet voor jou niet te moeilijk zijn.",
  o = "Breng 6 Thick Armor Kits en een Wildvine naar Jangdor Swiftstrider in Camp Mojache.",
  p = "Heb je de zes Thick Armor Kits en de Wildvine die ik nodig heb?$b$bZie het maken van pantserkits als een les in rustig en betrouwbaar werken. Je ontwikkelt een vaste werkwijze terwijl je deze kits maakt. Die helpt je om je vaardigheden te ontwikkelen voor het fijne werk dat nodig is voor Wild Leather-pantser.$b$bElke les heeft een doel, $N. Het is belangrijk om elke les op de juiste manier te omarmen.",
  c = "Deze pantserkits zijn van goede kwaliteit, $N. Er is één ding dat ik eis, niet alleen in mijn eigen werk maar ook in het werk van mijn leerlingen: kwaliteit.$b$bJe hebt dit patroon verdiend. Ik hoop dat het je net zoveel oplevert als het mij heeft opgeleverd.",
  g = { {"schouderstukken", "shoulder pieces"}, {"ondersteunen", "to support"}, {"drager", "wearer"}, {"uitstekende", "superior, excellent (uitstekend)"}, {"bescherming", "protection"}, {"verbetering", "enhancement"}, {"genaaid", "stitched (naaien)"}, {"betrouwbaar", "reliable"}, {"werkwijze", "method"}, {"ontwikkelt", "develop (ontwikkelen)"}, {"omarmen", "to embrace"}, {"eis", "demand (eisen)"}, {"oplevert", "brings, yields (opleveren)"} },
},

[2856] = { en = "Wild Leather Vest", tier = 3,
  t = "Wild Leather-vest",
  d = "Wild Leather-vesten zijn de basis van elke set Wild Leather-pantser. De vorm van het vest en de Wildvine die erin geweven is, geven een product dat de romp zo goed mogelijk beschermt. Tegelijk kan er sterke magie door het kledingstuk werken.$B$BVoor dit patroon heb ik twee Turtle Scale Breastplates nodig, twee paar Turtle Scale Gloves en een Wildvine. Dit is geen makkelijke les, maar je hebt zeker de vaardigheid om hem af te maken.",
  o = "Breng 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves en een Wildvine naar Jangdor Swiftstrider in Camp Mojache.",
  p = "Heb je de twee Turtle Scale Breastplates en Gloves? En vergeet de Wildvine niet!$b$bZelfs bij de eerste patronen leren we dat de basis van een vorm goed werkt bij moeilijkere kledingstukken. Het zijn verschillende voorwerpen, maar de vorm van de Turtle Scale Breastplates bereidt je voor op de details die je nodig hebt om een Wild Leather-vest te maken.$b$bNaarmate je verder komt in je lessen, wordt wat ik je leer echte kunst.",
  c = "Dit zijn heel mooie stukken, $N. Het vakmanschap en de zorg waarmee je ze gemaakt hebt, laten zien dat je jezelf helemaal aan deze taken wijdt.$b$bJe hebt gedaan wat ik vroeg, en daar hoort je beloning bij. De kennis om Wild Leather-vesten te maken is nu van jou!",
  g = { {"geweven", "woven (weven)"}, {"romp", "torso"}, {"zo goed mogelijk", "as well as possible"}, {"tegelijk", "at the same time"}, {"kledingstuk", "garment"}, {"bereidt je voor", "prepares you (voorbereiden)"}, {"naarmate", "as (gradually)"}, {"vakmanschap", "craftsmanship"}, {"wijdt", "dedicate (wijden)"}, {"beloning", "reward"} },
},

[2857] = { en = "Wild Leather Helmet", tier = 3,
  t = "Wild Leather-helm",
  d = "Een Wild Leather-helm beschermt de belangrijke delen van het hoofd uitstekend, zonder dat de drager comfort moet opgeven. Zoals bij al het Wild Leather-pantser geeft de ingewerkte Wildvine een krachtige maar willekeurige magische versterking aan de helm. Wie leer draagt, wil dit stuk zeker hebben!$B$BVoor dit patroon heb ik twee Nightscape Tunics, 2 Nightscape Headbands en een Wildvine nodig. Maak deze les af en het patroon is van jou!",
  o = "Breng 2 Nightscape Tunics, 2 Nightscape Headbands en een Wildvine naar Jangdor Swiftstrider in Camp Mojache.",
  p = "Ik wil dat je die tunieken en hoofdbanden maakt, en ik heb ook dat stuk Wildvine nodig. Pas daarna deel ik mijn kennis over Wild Leather-helmen met je.$b$bHoofddeksels zijn erg gewild onder avonturiers, of het nu een verrassend eenvoudige hoofdband is of een helm die het hele hoofd bedekt. De basis voor het maken van waardevolle hoofddeksels blijft hetzelfde, hoe ze er ook uitzien.",
  c = "Deze Nightscape-uitrusting voldoet precies aan de eisen die ik je heb gegeven, $N. Ik verwacht niets minder van een leerbewerker van jouw niveau.$b$bJe hebt de eer verdiend om Wild Leather-helmen te maken. Ik geef je dit patroon gratis en hoop dat je er goed aan verdient.",
  g = { {"opgeven", "to give up"}, {"ingewerkte", "integrated, worked in (inwerken)"}, {"versterking", "strengthening, enhancement"}, {"tunieken", "tunics (tuniek)"}, {"hoofdbanden", "headbands (hoofdband)"}, {"hoofddeksels", "head gear (hoofddeksel)"}, {"gewild", "sought after"}, {"bedekt", "covers (bedekken)"}, {"uitrusting", "equipment, gear"}, {"voldoet", "meets (voldoen)"}, {"eisen", "requirements (eis)"}, {"niveau", "level, caliber"} },
},

[2858] = { en = "Wild Leather Boots", tier = 3,
  t = "Wild Leather-laarzen",
  d = "Je kennis van Wild Leather-pantser groeit, $n, maar er is nog meer te leren.$B$BWild Leather-laarzen zijn de hoeksteen van elke set. Zulke laarzen zijn gemaakt om de voet comfortabel te omsluiten en hem te beschermen tegen de gevaren van het avonturen. De zachte zolen zijn een zegen voor wie zich stil wil bewegen.$B$BVoor dit patroon wil ik dat je twee Nightscape Pants en twee Nightscape Boots maakt. Ik heb ook twee Wildvines nodig... niet maar één. Als je deze voorwerpen hebt, gaan we verder.",
  o = "Breng 2 Nightscape Pants, 2 Nightscape Boots en 2 Wildvines naar Jangdor Swiftstrider in Camp Mojache.",
  p = "De broeken, laarzen en Wildvines moeten bij mij zijn voordat je het patroon leert, $N. Heb je gedaan wat ik vroeg?$b$bVanaf het eerste paar laarzen dat we leren maken, begrijpen we dat een goede laars precies het evenwicht moet houden tussen comfort en nut. Met allebei kunnen we voorwerpen maken waardoor de drager vermoeidheid kan negeren. Die vermoeidheid zou mensen met spullen van slechtere kwaliteit verlammen.",
  c = "Je hebt weer voorwerpen gemaakt met de vaardigheid van een ervaren vakman. Je hebt dit patroon verdiend, en ook mijn felicitaties.",
  g = { {"hoeksteen", "cornerstone"}, {"omsluiten", "to cradle, enclose"}, {"zolen", "soles (zool)"}, {"zegen", "blessing"}, {"evenwicht", "balance"}, {"nut", "function, usefulness"}, {"vermoeidheid", "fatigue"}, {"negeren", "to ignore"}, {"verlammen", "to cripple, paralyze"}, {"ervaren", "experienced"}, {"felicitaties", "congratulations"} },
},

[2859] = { en = "Wild Leather Leggings", tier = 3,
  t = "Wild Leather-beenstukken",
  d = "Je bent klaar voor moeilijkere lessen, $n. Wild Leather-beenstukken behoren tot de stevigste en krachtigste leren uitrusting die er is. De taille, de dijen, de kuiten en de belangrijke organen krijgen allemaal enorme bescherming. Samen met de versterking van de Wildvine zullen avonturiers die ze hebben je bedanken, elke keer dat ze je zien.$B$BOm dit patroon te krijgen, heb ik twee Turtle Scale Helms, twee Turtle Scale Bracers en twee Wildvines nodig.",
  o = "Breng 2 Turtle Scale Helms, 2 Turtle Scale Bracers en 2 Wildvines naar Jangdor Swiftstrider in Camp Mojache.",
  p = "Heb je de Turtle Scale Bracers en Helms klaar? Vergeet de twee Wildvines niet die ik nodig heb.$b$bInmiddels begin je te zien hoeveel kracht er in Wild Leather-pantser kan zitten. Een pantser dat je overal voor kunt gebruiken, is bijna onbetaalbaar voor een leerbewerker. De grenzen liggen alleen bij de hoeveelheid grondstoffen om de voorwerpen te maken - niet bij de kwaliteit van het eindresultaat!",
  c = "Weer heb je mijn opdracht zonder fouten gedaan. Misschien kom ik op een dag bij JOU om kennis te zoeken, hè $N?$b$bHier is het patroon voor de beenstukken, samen met mijn dank. Prent deze kennis goed in je geheugen, en laat je eindproducten je indrukwekkende vaardigheden gebruiken!",
  g = { {"beenstukken", "leggings, leg pieces"}, {"behoren tot", "are among"}, {"stevigste", "sturdiest (stevig)"}, {"taille", "waist"}, {"dijen", "thighs (dij)"}, {"kuiten", "calves (kuit)"}, {"organen", "organs, vitals (orgaan)"}, {"inmiddels", "by now"}, {"onbetaalbaar", "invaluable, priceless"}, {"grenzen", "limits (grens)"}, {"grondstoffen", "resources, raw materials"}, {"eindresultaat", "finished product"}, {"prent", "imprint (inprenten)"}, {"indrukwekkende", "impressive (indrukwekkend)"} },
},

[2860] = { en = "Master of the Wild Leather", tier = 3,
  t = "Meester van het Wild Leather",
  d = "$n, je hebt alles geleerd wat ik je kan leren. Er is echter nog één patroon voor Wild Leather-pantser over. Ik laat je hier niet onnodig hard voor werken. Je hebt het eerlijk verdiend, en meer dan dat. Maar dit patroon kan ik niet zomaar met je delen.$B$BMijn leraar, die mij het vak heeft geleerd, moet je belonen. Breng deze brief naar Una. Zij geeft les in leerbewerken in Thunder Bluff. Laat haar de brief zien, en laat haar je als gelijke erkennen, zoals ik doe.",
  o = "Geef Jangdor's Letter aan Una, de meester-leerbewerker van Thunder Bluff.",
  p = "Gegroet, $r... aan je gezicht zie ik dat je net als ik een leerbewerker bent. Ben je gekomen om iets van mijn vaardigheden te leren, of heb je iets anders met me te bespreken?",
  c = "Ah ja, Jangdor heeft je gestuurd. Het doet me plezier om te zien dat een van mijn beste leerlingen nu zelf een leerling heeft.$b$bZijn toewijding en zijn talent met leer zijn indrukwekkend. Dat hij je in deze brief zo prijst, is een teken van respect dat ik erken.$b$bIk weet dat hij je de kunst van Wild Leather heeft geleerd. Laat mij je opleiding afmaken met dit patroon. Gebruik het goed; weinigen in de wereld kennen de geheimen van Wild Leather-mantels.",
  g = { {"echter", "however"}, {"onnodig", "needlessly"}, {"zomaar", "just like that, freely"}, {"het vak", "the craft, trade"}, {"belonen", "to reward"}, {"gelijke", "equal"}, {"erkennen", "to acknowledge"}, {"gegroet", "greetings"}, {"toewijding", "dedication"}, {"prijst", "praise (prijzen)"}, {"opleiding", "training"}, {"mantels", "cloaks (mantel)"} },
},

[2936] = { en = "The Spider God", tier = 3,
  t = "De spinnengod",
  d = "De Witherbarks aanbidden een spinnengod, en van haar verzamelen ze hun sterkste gif. Dus als je het gif wilt, moet je hun god oproepen!$B$BDaarvoor moet je haar ware naam kennen. Die naam staat op een stenen tafel die begraven ligt in Tanaris, in de trollenstad Zul'Farrak, in een graftombe die wordt bewaakt door Theka the Martyr.$B$BVersla Theka, en zoek en lees zijn tafel om de naam van de spinnengod te ontdekken. Kom terug naar mij als je hem kent.",
  o = "Lees de Tablet of Theka om de naam van de spinnengod van de Witherbark te leren, en ga dan terug naar Master Gadrin.",
  p = "Ken je de naam van de spinnengod?",
  c = "Ah, Elortha no Shadra... spreek deze naam alleen fluisterend uit, want het uitspreken ervan heeft veel gewicht in de rijken van de geest.$b$bIk zal hem op perkament zetten en een oproepspreuk voor je maken...",
  e = "Vind de naam van de spinnengod",
  g = { {"aanbidden", "to worship"}, {"gif", "venom, poison"}, {"oproepen", "to summon"}, {"ware", "true (waar)"}, {"stenen tafel", "stone tablet"}, {"begraven", "buried"}, {"graftombe", "tomb"}, {"bewaakt", "guarded (bewaken)"}, {"fluisterend", "in a whisper"}, {"rijken", "realms (rijk)"}, {"perkament", "parchment"}, {"oproepspreuk", "summoning spell"} },
},

[6608] = { en = "You Too Good.", tier = 3,
  t = "Jij te goed.",
  d = "Lumak kan $N niks meer leren. Jij te goed! Zoek vriend van Lumak, Nat Pagle. Is mens, maar niet opeten! Is vriend van Lumak! Nat leert jou beter vissen.$B$BJij vindt Nat in Dustwallow Marsh, ten zuiden van mensenstad, Thermoro-ofzoiets. Nat waarschijnlijk vissen. Ga nu!",
  o = "Je denkt dat Lumak je probeert te vertellen dat hij je niet meer kan helpen om beter te vissen. Misschien kun je zijn vriend Nat Pagle zoeken. Hij is een mens die vist bij een van de eilanden ten zuiden van Theramore (dat denk je tenminste dat Lumak zei).",
  c = "Natuurlijk, jij bent vast een vriend van Lumak.$B$BVissen? Ik kan je alles over vissen vertellen.",
  g = { {"opeten", "to eat up"}, {"mensenstad", "human town"}, {"ofzoiets", "or something like that"}, {"waarschijnlijk", "probably"}, {"eilanden", "islands (eiland)"}, {"tenminste", "at least"}, {"vast", "surely, must be"} },
},

[6622] = { en = "Triage", tier = 3,
  t = "Triage",
  d = "Goedendag, dokter. Vanmiddag word je getest: kun je patiënten in de juiste volgorde behandelen? Als je voor je examen slaagt, word je opgenomen in het beroemde Horde Trauma.$B$BLet nu goed op! De kritiek gewonden moeten als eerste worden verzorgd. Na de kritieke gevallen komen de zwaargewonden. De lichtgewonden verzorg je als laatste. Je moet 15 patiënten redden om voor dit examen te slagen. Je zakt als 6 van je patiënten tijdens de triage sterven.$B$BJe krijgt triageverbanden.$B$BSucces, dokter.$b",
  o = "Red patiënten door hun wonden te verzorgen met Triage Bandages. Je moet 15 patiënten redden voordat 6 van hen aan hun verwondingen sterven.$B$BOnthoud de volgorde van de triage! Critically Injured Soldiers sterven het snelst, daarna Badly Injured Soldiers. Injured Soldiers sterven het langzaamst. Die moet je pas redden NADAT je de Critically Injured en Badly Injured Soldiers hebt behandeld.",
  p = "Wonderbaarlijk werk, dokter. Gewoon wonderbaarlijk.",
  c = "Dokter $N, welkom bij Horde Trauma.",
  e = "15 patiënten gered!",
  g = { {"triage", "sorting patients by urgency"}, {"behandelen", "to treat"}, {"slaagt", "pass (slagen)"}, {"opgenomen", "admitted (opnemen)"}, {"kritiek gewonden", "critically injured"}, {"zwaargewonden", "badly injured"}, {"verzorgd", "tended to (verzorgen)"}, {"zakt", "fail an exam (zakken)"}, {"verbanden", "bandages (verband)"}, {"verwondingen", "injuries (verwonding)"}, {"wonderbaarlijk", "miraculous"} },
},

[6623] = { en = "Horde Trauma", tier = 3,
  t = "Horde Trauma",
  d = "Dokter $N, neem ik aan. Fijn om je weer te zien.$B$BIk heb geweldig nieuws voor je! Doctor Gregory Victor, de hoofdarts van Horde Trauma, heeft persoonlijk gevraagd of je bij hem in Hammerfall komt. Dit kan de kans van je leven zijn! Ik zou alles geven voor de kans om bij de grote Doctor Gregory Victor te studeren! Laat deze kans niet lopen!",
  o = "Reis naar Hammerfall in de Arathi Highlands en praat met Doctor Gregory Victor over lid worden van Horde Trauma.$b",
  c = "Geweldig. Trek je operatiekleding aan, we beginnen meteen!",
  g = { {"neem ik aan", "I presume (aannemen)"}, {"hoofdarts", "chief physician"}, {"persoonlijk", "personally"}, {"de kans van je leven", "the opportunity of a lifetime"}, {"laat deze kans niet lopen", "don't miss this chance"}, {"lid worden", "to become a member, join"}, {"operatiekleding", "scrubs"}, {"meteen", "at once"} },
},

[243] = { en = "Into the Field", tier = 4,
  t = "Het veld in",
  d = "Je gaat naar de woestijn van Tanaris om de stevigheid van het weefsel te testen van de basilisken, scorpids en hyena's die daar leven. Verzamel weefselmonsters en gebruik ze met de testkit die je bij je hebt. Verwacht dat een deel van de monsters zal mislukken. Ik heb acht goede monsters van elke soort nodig.$B$BBovendien hebben de goblins van Gadgetzan een energiebron die je met dit soort aangepaste kit moet gebruiken. Praat met Chief Engineer Bilgewhizzle en vraag er een voor de kit.$B$BKom pas terug naar mij als het gelukt is.",
  o = "Praat met Chief Engineer Bilgewhizzle in Gadgetzan over een energiebron voor de testkit.",
  c = "Ah, onze energiebronnen van model 4711-FTZ! Normaal gebruiken we die om de waterputten van stroom te voorzien, maar DANKZIJ DIE GEMENE NOMADEN hebben we op dit moment veel te veel energiebronnen.$B$BTuurlijk, ik kan je een energiebron geven voor welk duister wetenschappelijk experiment je ook voor me probeert te verbergen. Maar gratis is het niet, $r. Niets is gratis in Gadgetzan.",
  g = { {"stevigheid", "firmness, consistency"}, {"weefsel", "tissue"}, {"basilisken", "basilisks (basilisk)"}, {"weefselmonsters", "tissue samples"}, {"mislukken", "to fail"}, {"bovendien", "in addition, besides"}, {"energiebron", "power source"}, {"aangepaste", "modified (aangepast)"}, {"waterputten", "water wells (waterput)"}, {"van stroom te voorzien", "to power"}, {"gemene", "vile, nasty (gemeen)"}, {"nomaden", "nomads (nomade)"}, {"duister", "sinister, nefarious"}, {"verbergen", "to hide"} },
},

[379] = { en = "Slake That Thirst", tier = 4,
  t = "Les die dorst",
  d = "Je wilt een energiebron. Daar kan ik je mee helpen. Weet je wat ik wil? Ik wil iets te drinken! Breng me vijf Wastewander Water Pouches, dan geef ik je de 4711-FTZ.$B$BNou... raad eens waar je Wastewander Water Pouches kunt vinden! Waarom loop je niet naar een van de Wastewander-nomaden ten oosten van hier om er eentje te vragen? Laat me weten hoe dat afloopt.",
  o = "Breng 5 Wastewander Water Pouches naar Chief Engineer Bilgewhizzle in Gadgetzan.",
  p = "Nou, hebben de nomaden je die waterzakken \"vrijwillig\" gegeven?",
  c = "Uitstekend, de energiebron is van jou. Hij is niet helemaal gemaakt voor gebruik in zo'n wetenschapskit. Je hebt dus maar beperkte tijd voordat alle gegevens die je verzamelt kaboem gaan!$B$BAls je alles hebt verzameld wat je nodig hebt voor wat je ook aan het doen bent, breng het dan naar mij. Dan zet ik hem netjes uit. Je hebt hooguit twee uur om af te maken wat je moet doen.$B$BAls het je niet op tijd lukt, kan ik je altijd een nieuwe energiebron verkopen om het opnieuw te proberen. Je hoorde het goed - verkopen!",
  g = { {"les", "quench, slake (lessen)"}, {"dorst", "thirst"}, {"raad eens", "guess (raden)"}, {"afloopt", "turns out (aflopen)"}, {"waterzakken", "water pouches (waterzak)"}, {"vrijwillig", "voluntarily"}, {"beperkte", "limited (beperkt)"}, {"gegevens", "data"}, {"kaboem", "kablooey, boom"}, {"netjes", "properly, neatly"}, {"hooguit", "at most"} },
},

[654] = { en = "Tanaris Field Sampling", tier = 4,
  t = "Veldonderzoek in Tanaris",
  d = "Als je de energiebron aanzet, begint de testkit te gloeien en te trillen. Het lijkt te werken zoals gepland.$B$BVolgens Chief Engineer Bilgewhizzle heb je nu twee uur om in de woestijn van Tanaris de gegevens te verzamelen die je nodig hebt. Als je ze niet binnen twee uur verzamelt, gaan alle gegevens verloren en moet je een nieuwe energiebron van hem kopen.$B$BGa terug naar hem als je de taak hebt voltooid.",
  o = "Verzamel goede monsters van 8 basilisken, 8 hyena's en 8 schorpioenen. Breng de testkit terug naar Chief Engineer Bilgewhizzle in Gadgetzan voordat de energiebron leeg is.",
  p = "Nou, heb je alles wat je nodig had? Als dat niet zo is en de stroom raakt op, is alles erin bedorven en moet je opnieuw beginnen.$B$BHé, kijk mij niet aan voor medelijden. Ik zorg er alleen voor dat de Gadgetzan Water Company winst maakt. Als dat betekent dat ik je energiebronnen verkoop tot we het ons kunnen veroorloven om water te importeren uit de ijskoude bronnen van Dun Morogh, dan is dat maar zo!",
  c = "Goed dan, ik heb maar een seconde nodig om de energiebron eruit te halen. Daarna kun je ermee doen wat je wilt, zonder dat je bang hoeft te zijn dat de gegevens erin verloren gaan.",
  g = { {"veldonderzoek", "field research"}, {"gloeien", "to glow"}, {"trillen", "to vibrate"}, {"zoals gepland", "as planned"}, {"verloren", "lost"}, {"schorpioenen", "scorpions (schorpioen)"}, {"raakt op", "runs out (opraken)"}, {"bedorven", "ruined, spoiled"}, {"medelijden", "sympathy, pity"}, {"winst", "profit"}, {"veroorloven", "to afford"}, {"bronnen", "springs (bron)"} },
},

[841] = { en = "Another Power Source?", tier = 4,
  t = "Nog een energiebron?",
  d = "Laat me raden - je hebt je wereldvernietigende, duistere daad niet op tijd af gekregen. Nee wacht, nog beter... je hebt hem in het zand laten vallen! Nou, wat de reden ook is, ik heb nog meer energiebronnen die ik je kan verkopen. Maar deze keer kost het je tien, JA TIEN Wastewander Water Pouches!$B$BHet zijn overal zware tijden, $n, en energiebronnen groeien niet aan bomen! Hm, maar wat als dat wel zo was? Misschien kunnen we een energiebronnenboom MAKEN...",
  o = "Breng 10 Wastewander Water Pouches naar Chief Engineer Bilgewhizzle in Gadgetzan in ruil voor een nieuwe energiebron.",
  p = "Nou, heb je de tien waterzakken?",
  c = "Goed dan, hier is nog een energiebron. Ik raad je echt aan om hem deze keer goed te gebruiken, tenzij je graag nog tien waterzakken uitgeeft voor nog een waterbron.",
  g = { {"raden", "to guess"}, {"wereldvernietigende", "world-ending"}, {"daad", "deed"}, {"af gekregen", "got done (afkrijgen)"}, {"zware tijden", "tough times"}, {"in ruil voor", "in exchange for"}, {"raad je aan", "recommend (aanraden)"}, {"tenzij", "unless"}, {"uitgeeft", "spend (uitgeven)"} },
},

[32] = { en = "Rise of the Silithid", tier = 4,
  t = "De opkomst van de silithid",
  d = "Hier is je rapport. Ik raad je dringend aan om het naar iemand te brengen die verstand heeft van dit soort dingen.$B$BIk ken een trollengeleerde die Zilzibin Drumlore heet. Hij heeft veel tijd besteed aan het bestuderen van levensvormen die alleen in de natuur van Azeroth voorkomen. Bovendien is hij ook nog historicus! Als je iemand wilt die je helpt uitzoeken wat deze dreiging precies is en hoe je haar kunt stoppen, geef dit rapport dan aan hem. We hebben alle hulp nodig die we kunnen krijgen.$B$BZil woont in een huis op de tweede verdieping van de Drag in Orgrimmar.",
  o = "Breng het rapport naar Zilzibin Drumlore in Orgrimmar.",
  p = "Het spijt me, ik ken je niet... maar zo te zien heb je in elk geval iets over mij gehoord. Waarmee kan ik je helpen? Heb je iets voor me?",
  c = "Dit rapport... Ik heb eerder met deze beesten te maken gehad. Fizzledowser was wijs om dit, en jou, naar mij te sturen.$B$BDeze wezens zullen de woestijn van Tanaris snel opvreten. Ze zijn niets minder dan een van de grootste gevaren waar we ooit voor zullen staan. Onthoud deze naam goed, $n: silithid. De insecten in dit rapport zijn de silithid, en ze zijn de werktuigen van een van de grootste dreigingen voor zowel de Horde als de Alliance.$B$BWaren we maar slim genoeg geweest om dat eerder te zien.",
  g = { {"opkomst", "rise"}, {"dringend", "urgently"}, {"verstand heeft van", "knows about"}, {"geleerde", "scholar"}, {"levensvormen", "life forms (levensvorm)"}, {"voorkomen", "occur"}, {"historicus", "historian"}, {"dreiging", "threat"}, {"verdieping", "floor, tier"}, {"opvreten", "to devour, consume"}, {"niets minder dan", "nothing short of"}, {"werktuigen", "tools (werktuig)"}, {"waren we maar", "if only we had been"} },
},

[4509] = { en = "Calm Before the Storm", tier = 4,
  t = "De stilte voor de storm",
  d = "Mijn recente ontdekkingen en de kennis die we hier vandaag hebben opgedaan, moeten terechtkomen in handen die er misschien echt iets mee kunnen doen. Hoe vindingrijk we hier in Gadgetzan ook zijn, we kunnen dit niet alleen.$B$BBreng mijn nieuwste rapport naar Zilzibin Drumlore in Orgrimmar. Hij woont toch nog steeds op het bovenste deel van de Drag? Hij heeft vrienden hoog in de Horde. Als we hen hierbij kunnen betrekken, $N, dan komen we hier misschien levend uit.",
  o = "Breng Pestlezugg's Un'Goro Report naar Zilzibin Drumlore in Orgrimmar.",
  p = "Het zijn dwazen, $N! Ze denken er niet eens aan om om zich heen te kijken naar een grotere dreiging. Hun onredelijke haat tegen de Alliance wordt onze ondergang. Ik weet niet hoeveel meer bewijs van de silithid-dreiging ik ze nog kan geven, behalve ze in een van de nesten te gooien zodat ze het zelf zien!$B$BSorry, heb je nieuws voor me?",
  c = "Ik waardeer dit echt, maar ik weet niet zeker wat het ons zal opleveren. De Horde negeert elke dreiging die niet van de Alliance komt. Thrall zelf zou misschien iets doen als de feiten aan hem werden voorgelegd, maar hij krijgt van alle kanten tegenstrijdig advies. Deze dwazen zouden ons achter onze eigen ingebeelde staart aan laten jagen, als ze dachten dat ze de Alliance daarmee konden verrassen!$B$BJe hebt de dreiging zelf gezien, $N. We moeten vastberaden blijven om de silithid te verslaan!",
  g = { {"ontdekkingen", "findings (ontdekking)"}, {"opgedaan", "gained (opdoen)"}, {"terechtkomen", "to end up"}, {"vindingrijk", "resourceful"}, {"betrekken", "to involve"}, {"dwazen", "fools (dwaas)"}, {"onredelijke", "irrational (onredelijk)"}, {"ondergang", "undoing, downfall"}, {"nesten", "hives, nests (nest)"}, {"waardeer", "appreciate (waarderen)"}, {"voorgelegd", "presented (voorleggen)"}, {"tegenstrijdig", "conflicting"}, {"ingebeelde", "imaginary (ingebeeld)"}, {"verrassen", "to catch unawares, surprise"}, {"vastberaden", "committed, determined"} },
},

[5145] = { en = "Dragonscale Leatherworking", tier = 4,
  t = "Leerbewerken met drakenschubben",
  d = "Leerbewerken met drakenschubben is niet makkelijk, maar het levert heel veel op. Ik leer je hoe je dit mooie maliënpantser maakt, maar alleen als je akkoord gaat met bepaalde voorwaarden.$B$BAls je voor deze weg kiest, beloof je dat je nooit elementair of tribaal leerbewerken zult leren. Aan de top van het vak is maar plaats voor één van de drie. Verder wil ik een paar voorbeelden zien van je beste werk met scorpid-pantser. Tot slot wil ik bewijs dat je de basis van het vak kunt verzamelen: de schubben van het drakenvolk.",
  o = "Breng 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves en 10 Worn Dragonscales naar Thorkaf Dragoneye in de Badlands.$B$BAls je deze quest voltooit, krijg je toegang tot de kunst van Dragonscale Leatherworking.$B$BAls je deze quest voltooit, kun je Elemental Leatherworking en Tribal Leatherworking niet meer leren. Wees er zeker van dat je deze weg wilt volgen voordat je dat doet.",
  p = "Ben je klaar voor een blijvende beslissing, door leerbewerker met drakenschubben te worden? Dan ben ik klaar om je als leerling aan te nemen. Breng me gewoon wat ik gevraagd heb, en dan beginnen we met je opleiding.",
  c = "Dat moet ik je nageven - er is een sterke wil nodig om zo'n blijvende beslissing te nemen als jij net deed. Ik verzeker je dat leerbewerken met drakenschubben een winstgevende en lonende weg voor je zal zijn.$b$bWil je later verder trainen in deze kunst, praat dan gewoon met me. Dan geef ik je alle kennis die je nog niet hebt geleerd.",
  g = { {"drakenschubben", "dragon scales (drakenschub)"}, {"levert heel veel op", "is very rewarding (opleveren)"}, {"maliënpantser", "mail armor"}, {"akkoord gaat", "agree (akkoord gaan)"}, {"voorwaarden", "conditions (voorwaarde)"}, {"elementair", "elemental"}, {"tribaal", "tribal"}, {"tot slot", "finally"}, {"schubben", "scales (schub)"}, {"drakenvolk", "dragonkin"}, {"voltooit", "complete (voltooien)"}, {"blijvende", "permanent (blijvend)"}, {"dat moet ik je nageven", "I'll hand it to you"}, {"verzeker", "assure (verzekeren)"}, {"winstgevende", "profitable (winstgevend)"}, {"lonende", "rewarding (lonend)"} },
},

[5146] = { en = "Elemental Leatherworking", tier = 4,
  t = "Elementair leerbewerken",
  d = "Elementair leerbewerken is wat ik ken. Als je bereid bent je geest te openen voor de grotere krachten van de materie, deel ik alles met je wat er te leren valt.$B$BWeet dit, $c: als je voor deze weg kiest, beloof je dat je nooit leerbewerken met drakenschubben of tribaal leerbewerken zult leren. Er is maar plaats om één van de drie kunsten te beoefenen. Verder wil ik goed bewijs dat je in harmonie bent met de elementen van de natuur. Breng me daarom de zuiverste essenties van vuur, water, aarde en wind.",
  o = "Breng 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth en 2 Breath of Wind naar Brumn Winterhoof in de Arathi Mountains.$B$BAls je deze quest voltooit, krijg je toegang tot de kunst van Elemental Leatherworking.$B$BAls je deze quest voltooit, kun je Dragonscale Leatherworking en Tribal Leatherworking niet meer leren. Wees er zeker van dat je deze weg wilt volgen voordat je dat doet.",
  p = "Om zulk pantser van leer te maken, heb je geduld en toewijding nodig. Als je eenmaal voor de elementen hebt gekozen, kun je ze niet meer de rug toekeren. Breng me bewijs dat je het waard bent, en dan beginnen we.",
  c = "Je hebt je keuze gemaakt, en de elementen aanvaarden je. Als ik klaar ben met je opleiding, zul je de wil bezitten om de beste leren kleding te maken.$B$BWil je later verder trainen in deze kunst, praat dan gewoon met me. Dan geef ik je alle kennis die je nog niet hebt geleerd.",
  g = { {"bereid", "willing"}, {"geest", "mind"}, {"materie", "substance, matter"}, {"beoefenen", "to practice"}, {"in harmonie", "in tune"}, {"zuiverste", "purest (zuiver)"}, {"essenties", "essences (essentie)"}, {"geduld", "patience"}, {"eenmaal", "once"}, {"de rug toekeren", "to turn your back on"}, {"het waard bent", "are worthy"}, {"aanvaarden", "accept (aanvaarden)"}, {"bezitten", "to possess"} },
},

[5148] = { en = "Tribal Leatherworking", tier = 4,
  t = "Tribaal leerbewerken",
  d = "Om tribaal leerbewerken te leren, moet je begrijpen hoe oorspronkelijk de natuur werkelijk is. Ik weet dat je de kunst van het maken van Wild Leather-pantser al beheerst, en ik ben bereid je opleiding af te maken.$B$BWeet dit, $c: als je voor deze weg kiest, beloof je dat je nooit leerbewerken met drakenschubben of elementair leerbewerken zult leren. Er is maar plaats om één van de drie kunsten te beoefenen. Breng me verder de beste voorbeelden van je Wild Leather-pantser. Daarna beginnen we aan je weg naar meesterschap.",
  o = "Breng een Wild Leather Vest en een Wild Leather Helmet naar Se'Jib in Stranglethorn Vale.$B$BAls je deze quest voltooit, krijg je toegang tot de kunst van Tribal Leatherworking.$B$BAls je deze quest voltooit, kun je Dragonscale Leatherworking en Elemental Leatherworking niet meer leren. Wees er zeker van dat je deze weg wilt volgen voordat je dat doet.",
  p = "De natuur is een kracht die je tevreden moet stellen voordat je kunt hopen te leren hoe je haar wil in je leren kleding buigt. Breng me je offer aan deze kracht, en ik zorg ervoor dat je gehoord wordt.",
  c = "Je hebt je beste offers gegeven, en de natuur zal je snel toestaan haar naar je wil te buigen. Als ik klaar ben met je opleiding, wordt je werk zelf een natuurkracht.$B$BWil je later verder trainen in deze kunst, praat dan gewoon met me. Dan geef ik je alle kennis die je nog niet hebt geleerd.",
  g = { {"oorspronkelijk", "primal, original"}, {"werkelijk", "truly"}, {"meesterschap", "mastery"}, {"tevreden moet stellen", "must appease (tevredenstellen)"}, {"buigt", "bend (buigen)"}, {"offer", "offering"}, {"toestaan", "to permit"}, {"natuurkracht", "force of nature"} },
},

